export function parseQuery(input: string): Query {
  if (!input || input.trim() === '') {
    throw new Error('Empty input');
  }
  const tokens = input.trim().split(/\s+/);
  if (tokens.length === 0) {
    throw new Error('No tokens');
  }
  return {
    command: tokens[0],
    args: tokens.slice(1),
    raw: input.trim(),
  };
}

export interface Query {
  command: string;
  args: string[];
  raw: string;
}
